/// <summary>
///    The <c>METItemPackChangeBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide item status change business event.
/// </summary>
[BusinessEvents(classStr(METItemPackChangeBusinessEventContract),
    "@MET:ItemPackChangeBusinessEventName",
    "@MET:ItemPackChangeBusinessEventDesc",
    ModuleAxapta::Inventory)]
public final class METItemPackChangeBusinessEvent extends BusinessEventsBase
{
    private MetItemSiteSettingsSetup metItemSiteSettingsSetup;
       
}

Method.Source:
    /// <summary>
    /// Constructs a new METItemPackChangeBusinessEvent business event.
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetup">The <c>MetItemSiteSettingsSetup</c> record.</param>
    /// <returns>A new <c>METItemPackChangeBusinessEvent</c> business event.</returns>
    public static METItemPackChangeBusinessEvent newFromMetItemSiteSettingsSetup(MetItemSiteSettingsSetup _metItemSiteSettingsSetup)
    {
        METItemPackChangeBusinessEvent event = new METItemPackChangeBusinessEvent();
        event.parmMetItemSiteSettingsSetup(_metItemSiteSettingsSetup);

        return event;
    }

    /// <summary>
    /// parm method to set/get <t>MetItemSiteSettingsSetup</t> buffer.
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetup">MetItemSiteSettingsSetup buffer></param>
    /// <returns><t>MetItemSiteSettingsSetup</t> buffer</returns>
    private MetItemSiteSettingsSetup parmMetItemSiteSettingsSetup(MetItemSiteSettingsSetup _metItemSiteSettingsSetup = metItemSiteSettingsSetup)
    {
        metItemSiteSettingsSetup = _metItemSiteSettingsSetup;

        return metItemSiteSettingsSetup;
    }

/// <summary>
/// Overrides to provide item status change data.
/// </summary>
/// <returns>The <c>METItemPackChangeBusinessEventContract</c> of the event.</returns>
public BusinessEventsContract buildContract()
{
    return METItemPackChangeBusinessEventContract::newFromMetItemSiteSettingsSetup(metItemSiteSettingsSetup);
}
